const input = $input.first().json || {};
const accountId = String(input.account_id || '').trim();
const workspaceId = String(input.workspace_id || '').trim();
const accountSlug = String(input.account_slug || '').trim();

if (!accountId || !workspaceId) {
  throw new Error('missing_account_context');
}

return [{
  json: {
    ...input,
    account_id: accountId,
    workspace_id: workspaceId,
    account_slug: accountSlug,
  },
}];

const response = $input.first().json || {};
const context = $('Normalize Product Account Context').first().json || {};
const usage = response.usageMetadata || {};
const startedAt = Date.parse(context.started_at || '');
const latencyMs = Number.isFinite(startedAt) ? Date.now() - startedAt : null;
const inputTokens = Number(usage.promptTokenCount ?? 0);
const outputTokens = Number(usage.candidatesTokenCount ?? 0);
const totalTokens = Number(usage.totalTokenCount ?? inputTokens + outputTokens);

return [{
  json: {
    account_id: context.account_id,
    workspace_id: context.workspace_id,
    usage_event_id: `cp_usage_${context.workflow_id}_${context.execution_id}_${context.node_id}`,
    account_slug: context.account_slug,
    workflow_id: context.workflow_id,
    workflow_name: context.workflow_name,
    execution_id: context.execution_id,
    node_id: context.node_id,
    node_name: context.node_name,
    provider: context.provider,
    service_name: context.service_name,
    model_name: context.model_name,
    model: context.model_name,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    total_tokens: totalTokens,
    estimated_cost: 0,
    latency_ms: latencyMs,
    usage_at: new Date().toISOString(),
    workflow: context.workflow_name,
    n8n_execution_id: context.execution_id,
    node: context.node_name,
    environment: context.environment,
    business_action: context.business_action,
    litellm_request_id: null,
    tags: ['costpilot', 'product-pql', 'gemini'],
    completion_result: response.candidates?.[0]?.content?.parts?.[0]?.text ?? null,
  },
}];

const result = $input.first().json || {};
const usage = $('Normalize Gemini Usage').first().json || {};
return [{
  json: {
    ingest_status: result.status,
    usage_event_id: result.usage_event_id,
    usage_record_id: result.usage_record_id,
    provider_connection_id: result.provider_connection_id,
    provider: result.provider,
    total_tokens: result.total_tokens,
    calculated_cost: result.calculated_cost,
    source_usage: usage,
  },
}];

const lifecycleRows = $input.first().json;
const ingest = $('Inspect Ingestion Result').first().json || {};
return [{
  json: {
    usage_ingest_status: ingest.ingest_status,
    usage_event_id: ingest.usage_event_id,
    total_tokens: ingest.total_tokens,
    calculated_cost: ingest.calculated_cost,
    activation: Array.isArray(lifecycleRows) ? lifecycleRows[0] ?? null : lifecycleRows,
  },
}];
